#!/usr/bin/env bash
set -euo pipefail

# Compiles assets/Bruk.icon into a native macOS Liquid Glass asset catalog
# (Assets.car) and wires CFBundleIconName into a packaged .app bundle when
# Xcode's `actool` is available. Falls back gracefully to the AppIcon.icns
# already generated by `nsh package` from assets/icon.png.

APP_BUNDLE="${1:-.nsh/out/Bruk.app}"
ICON_BUNDLE="${2:-assets/Bruk.icon}"
ICON_NAME="$(basename "$ICON_BUNDLE" .icon)"

if [ ! -d "$APP_BUNDLE" ]; then
  echo "error: app bundle not found at $APP_BUNDLE" >&2
  exit 1
fi

if [ ! -d "$ICON_BUNDLE" ]; then
  echo "error: icon bundle not found at $ICON_BUNDLE" >&2
  exit 1
fi

if ! xcrun --find actool >/dev/null 2>&1; then
  echo "note: Xcode actool not found; keeping AppIcon.icns from assets/icon.png (install Xcode to compile $ICON_BUNDLE into Assets.car)"
  exit 0
fi

RESOURCES_DIR="$APP_BUNDLE/Contents/Resources"
INFO_PLIST="$APP_BUNDLE/Contents/Info.plist"
TMP_DIR="$(mktemp -d)"
trap 'rm -rf "$TMP_DIR"' EXIT

xcrun actool "$ICON_BUNDLE" \
  --compile "$RESOURCES_DIR" \
  --output-format human-readable-text \
  --notices \
  --warnings \
  --errors \
  --output-partial-info-plist "$TMP_DIR/assetcatalog_generated_info.plist" \
  --app-icon "$ICON_NAME" \
  --include-all-app-icons \
  --enable-on-demand-resources NO \
  --development-region en \
  --target-device mac \
  --minimum-deployment-target 14.0 \
  --platform macosx

if /usr/libexec/PlistBuddy -c "Print :CFBundleIconName" "$INFO_PLIST" >/dev/null 2>&1; then
  /usr/libexec/PlistBuddy -c "Set :CFBundleIconName $ICON_NAME" "$INFO_PLIST"
else
  /usr/libexec/PlistBuddy -c "Add :CFBundleIconName string $ICON_NAME" "$INFO_PLIST"
fi

# Re-sign the bundle ad hoc after updating Contents/Resources and Info.plist
codesign --force --sign - --timestamp=none "$APP_BUNDLE"
echo "Compiled $ICON_BUNDLE into $RESOURCES_DIR/Assets.car (CFBundleIconName=$ICON_NAME)"
